record.field:
picking = env['stock.picking'].browse(record.res_id).exists()

if picking and not picking.move_ids:
    feedback = (
        'Không thể xác nhận Picking %s: '
        'Phiếu chưa có Stock Move (dòng sản phẩm).'
    ) % picking.name

    picking.message_post_with_source(
        'mail.message_activity_done',
        render_values={
            'activity': record,
            'feedback': feedback,
            'display_assignee': record.user_id != env.user,
        },
        mail_activity_type_id=record.activity_type_id.id,
        subtype_xmlid='mail.mt_activities',
    )

picking = env['stock.picking'].browse(record.res_id).exists()

if picking and picking.state == 'draft':
    picking.action_confirm()
    if not picking.move_ids:
        env.ref(
            'fmcg_business_automation.action_feedback_picking_missing_moves'
        ).with_context(
            active_model='mail.activity',
            active_id=record.id,
            active_ids=[record.id],
        ).run()

        activity_type = env.ref(
            'fmcg_business_automation.mail_activity_type_picking_add_move'
        )
        picking.activity_schedule(
            activity_type_id=activity_type.id,
            summary='Add missing Stock Move',
            user_id=record.user_id.id or env.user.id,
        )
    else:
        if picking.state == 'draft':
            raise UserError(
                'Picking %s vẫn đang ở trạng thái Draft sau khi xác nhận.'
                % picking.name
            )
